#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef enum {
    TYPE_NIL,
    TYPE_NUMBER,
    TYPE_SYMBOL,
    TYPE_CONS,
    TYPE_BUILTIN,
    TYPE_LAMBDA
} Type;

typedef struct Value Value;
typedef struct Env Env;
typedef Value* (*BuiltinFn)(Value* args, Env* env);

struct Value {
    Type type;
    union {
        long num;
        char* sym;
        struct { Value* car; Value* cdr; } cons;
        BuiltinFn builtin;
        struct { Value* params; Value* body; Env* closure; } lambda;
    } u;
};

typedef struct Binding {
    char* name;
    Value* value;
    struct Binding* next;
} Binding;

struct Env {
    Binding* bindings;
    Env* parent;
};

static Value nil_value;
static Value* NIL = &nil_value;

static Value* new_value(Type type) {
    Value* v = malloc(sizeof(Value));
    if (!v) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    v->type = type;
    memset(&v->u, 0, sizeof(v->u));
    return v;
}

Value* make_nil(void) {
    return NIL;
}

Value* make_number(long n) {
    Value* v = new_value(TYPE_NUMBER);
    v->u.num = n;
    return v;
}

Value* make_symbol(const char* name) {
    Value* v = new_value(TYPE_SYMBOL);
    v->u.sym = malloc(strlen(name) + 1);
    if (!v->u.sym) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    strcpy(v->u.sym, name);
    return v;
}

Value* make_cons(Value* car, Value* cdr) {
    Value* v = new_value(TYPE_CONS);
    v->u.cons.car = car;
    v->u.cons.cdr = cdr;
    return v;
}

Value* make_builtin(BuiltinFn fn) {
    Value* v = new_value(TYPE_BUILTIN);
    v->u.builtin = fn;
    return v;
}

Value* make_lambda(Value* params, Value* body, Env* closure) {
    Value* v = new_value(TYPE_LAMBDA);
    v->u.lambda.params = params;
    v->u.lambda.body = body;
    v->u.lambda.closure = closure;
    return v;
}

static int is_nil(Value* v) {
    return v && v->type == TYPE_NIL;
}

static int is_number(Value* v) {
    return v && v->type == TYPE_NUMBER;
}

static int is_symbol(Value* v) {
    return v && v->type == TYPE_SYMBOL;
}

static int is_cons(Value* v) {
    return v && v->type == TYPE_CONS;
}

static int is_builtin(Value* v) {
    return v && v->type == TYPE_BUILTIN;
}

static int is_lambda(Value* v) {
    return v && v->type == TYPE_LAMBDA;
}

static int is_symbol_named(Value* v, const char* name) {
    return is_symbol(v) && strcmp(v->u.sym, name) == 0;
}

static int truthy(Value* v) {
    return v && v->type != TYPE_NIL;
}

static Env* env_new(Env* parent) {
    Env* env = malloc(sizeof(Env));
    if (!env) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    env->bindings = NULL;
    env->parent = parent;
    return env;
}

static Binding* binding_find_local(Env* env, const char* name) {
    Binding* b = env ? env->bindings : NULL;
    while (b) {
        if (strcmp(b->name, name) == 0) return b;
        b = b->next;
    }
    return NULL;
}

static void env_define(Env* env, const char* name, Value* value) {
    Binding* b = malloc(sizeof(Binding));
    if (!b) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    b->name = malloc(strlen(name) + 1);
    if (!b->name) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    strcpy(b->name, name);
    b->value = value;
    b->next = env->bindings;
    env->bindings = b;
}

static Value* env_get(Env* env, const char* name) {
    while (env) {
        Binding* b = binding_find_local(env, name);
        if (b) return b->value;
        env = env->parent;
    }
    return NULL;
}

static int env_set(Env* env, const char* name, Value* value) {
    while (env) {
        Binding* b = binding_find_local(env, name);
        if (b) {
            b->value = value;
            return 1;
        }
        env = env->parent;
    }
    return 0;
}

typedef struct {
    const char* input;
    size_t pos;
} Reader;

static void skip_ws(Reader* r) {
    for (;;) {
        char c = r->input[r->pos];
        if (isspace((unsigned char)c)) {
            r->pos++;
        } else if (c == ';') {
            while (r->input[r->pos] && r->input[r->pos] != '\n') r->pos++;
        } else {
            break;
        }
    }
}

static int is_delimiter(char c) {
    return c == '\0' || isspace((unsigned char)c) || c == '(' || c == ')' ||
           c == '\'' || c == '`' || c == ',' || c == ';';
}

static Value* parse_expr(Reader* r);

static Value* parse_list(Reader* r) {
    Value* head = NIL;
    Value* tail = NULL;
    r->pos++;
    for (;;) {
        skip_ws(r);
        if (r->input[r->pos] == ')') {
            r->pos++;
            return head;
        }
        if (r->input[r->pos] == '\0') return head;
        Value* item = parse_expr(r);
        if (!item) return head;
        Value* cell = make_cons(item, NIL);
        if (is_nil(head)) {
            head = cell;
        } else {
            tail->u.cons.cdr = cell;
        }
        tail = cell;
    }
}

static Value* parse_symbol(Reader* r) {
    size_t start = r->pos;
    while (!is_delimiter(r->input[r->pos])) r->pos++;
    size_t len = r->pos - start;
    char* name = malloc(len + 1);
    if (!name) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    memcpy(name, r->input + start, len);
    name[len] = '\0';
    Value* v = make_symbol(name);
    free(name);
    return v;
}

static Value* parse_expr(Reader* r) {
    skip_ws(r);
    char c = r->input[r->pos];

    if (c == '\0') return NULL;

    if (c == '(') return parse_list(r);
    if (c == ')') {
        r->pos++;
        return NULL;
    }

    if (c == '\'') {
        r->pos++;
        Value* q = parse_expr(r);
        if (!q) q = make_nil();
        return make_cons(make_symbol("quote"), make_cons(q, NIL));
    }

    if (c == '`') {
        r->pos++;
        Value* q = parse_expr(r);
        if (!q) q = make_nil();
        return make_cons(make_symbol("quasiquote"), make_cons(q, NIL));
    }

    if (c == ',') {
        r->pos++;
        if (r->input[r->pos] == '@') {
            r->pos++;
            Value* q = parse_expr(r);
            if (!q) q = make_nil();
            return make_cons(make_symbol("unquote-splicing"), make_cons(q, NIL));
        }
        Value* q = parse_expr(r);
        if (!q) q = make_nil();
        return make_cons(make_symbol("unquote"), make_cons(q, NIL));
    }

    if (isdigit((unsigned char)c) || (c == '-' && isdigit((unsigned char)r->input[r->pos + 1]))) {
        char* end = NULL;
        long n = strtol(r->input + r->pos, &end, 10);
        r->pos = (size_t)(end - r->input);
        return make_number(n);
    }

    return parse_symbol(r);
}

static void print_value_to(FILE* out, Value* v) {
    if (!v || v->type == TYPE_NIL) {
        fputs("()", out);
    } else if (v->type == TYPE_NUMBER) {
        fprintf(out, "%ld", v->u.num);
    } else if (v->type == TYPE_SYMBOL) {
        fputs(v->u.sym, out);
    } else if (v->type == TYPE_BUILTIN) {
        fputs("#<builtin>", out);
    } else if (v->type == TYPE_LAMBDA) {
        fputs("#<lambda>", out);
    } else if (v->type == TYPE_CONS) {
        fputc('(', out);
        Value* p = v;
        int first = 1;
        while (is_cons(p)) {
            if (!first) fputc(' ', out);
            print_value_to(out, p->u.cons.car);
            first = 0;
            p = p->u.cons.cdr;
        }
        if (!is_nil(p)) {
            fputs(" . ", out);
            print_value_to(out, p);
        }
        fputc(')', out);
    }
}

void print_value(Value* v) {
    print_value_to(stdout, v);
}
