static Value* eval(Value* expr, Env* env);
static Value* apply(Value* fn, Value* args, Env* env);
static Value* eval_sequence(Value* body, Env* env);
static Value* qq_eval(Value* expr, Env* env, int depth);

static Value* runtime_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
    return make_nil();
}

static Value* append_two(Value* a, Value* b) {
    if (is_nil(a)) return b;
    if (!is_cons(a)) return runtime_error("append: expected a list");
    Value* result = make_cons(a->u.cons.car, NIL);
    Value* tail = result;
    Value* p = a->u.cons.cdr;
    while (is_cons(p)) {
        Value* cell = make_cons(p->u.cons.car, NIL);
        tail->u.cons.cdr = cell;
        tail = cell;
        p = p->u.cons.cdr;
    }
    if (!is_nil(p)) return runtime_error("append: improper list");
    tail->u.cons.cdr = b;
    return result;
}

static Value* builtin_add(Value* args, Env* env) {
    (void)env;
    long sum = 0;
    while (is_cons(args)) {
        Value* v = args->u.cons.car;
        if (!is_number(v)) return runtime_error("+ expects numbers");
        sum += v->u.num;
        args = args->u.cons.cdr;
    }
    return make_number(sum);
}

static Value* builtin_sub(Value* args, Env* env) {
    (void)env;
    if (!is_cons(args)) return runtime_error("- expects at least one argument");
    Value* first = args->u.cons.car;
    if (!is_number(first)) return runtime_error("- expects numbers");
    if (is_nil(args->u.cons.cdr)) return make_number(-first->u.num);
    long result = first->u.num;
    args = args->u.cons.cdr;
    while (is_cons(args)) {
        Value* v = args->u.cons.car;
        if (!is_number(v)) return runtime_error("- expects numbers");
        result -= v->u.num;
        args = args->u.cons.cdr;
    }
    return make_number(result);
}

static Value* builtin_mul(Value* args, Env* env) {
    (void)env;
    long result = 1;
    while (is_cons(args)) {
        Value* v = args->u.cons.car;
        if (!is_number(v)) return runtime_error("* expects numbers");
        result *= v->u.num;
        args = args->u.cons.cdr;
    }
    return make_number(result);
}

static Value* builtin_div(Value* args, Env* env) {
    (void)env;
    if (!is_cons(args)) return runtime_error("/ expects at least one argument");
    Value* first = args->u.cons.car;
    if (!is_number(first)) return runtime_error("/ expects numbers");
    if (is_nil(args->u.cons.cdr)) {
        if (first->u.num == 0) return runtime_error("division by zero");
        return make_number(1 / first->u.num);
    }
    long result = first->u.num;
    args = args->u.cons.cdr;
    while (is_cons(args)) {
        Value* v = args->u.cons.car;
        if (!is_number(v)) return runtime_error("/ expects numbers");
        if (v->u.num == 0) return runtime_error("division by zero");
        result /= v->u.num;
        args = args->u.cons.cdr;
    }
    return make_number(result);
}

static int value_equal(Value* a, Value* b) {
    if (a == b) return 1;
    if (!a || !b) return 0;
    if (a->type != b->type) return 0;
    if (a->type == TYPE_NIL) return 1;
    if (a->type == TYPE_NUMBER) return a->u.num == b->u.num;
    if (a->type == TYPE_SYMBOL) return strcmp(a->u.sym, b->u.sym) == 0;
    return 0;
}

static Value* builtin_eq(Value* args, Env* env) {
    (void)env;
    if (is_nil(args) || is_nil(args->u.cons.cdr)) return make_nil();
    Value* a = args->u.cons.car;
    Value* b = args->u.cons.cdr->u.cons.car;
    return value_equal(a, b) ? make_symbol("t") : make_nil();
}

static Value* builtin_lt(Value* args, Env* env) {
    (void)env;
    if (is_nil(args) || is_nil(args->u.cons.cdr)) return runtime_error("< expects two arguments");
    Value* a = args->u.cons.car;
    Value* b = args->u.cons.cdr->u.cons.car;
    if (!is_number(a) || !is_number(b)) return runtime_error("< expects numbers");
    return a->u.num < b->u.num ? make_symbol("t") : make_nil();
}

static Value* builtin_gt(Value* args, Env* env) {
    (void)env;
    if (is_nil(args) || is_nil(args->u.cons.cdr)) return runtime_error("> expects two arguments");
    Value* a = args->u.cons.car;
    Value* b = args->u.cons.cdr->u.cons.car;
    if (!is_number(a) || !is_number(b)) return runtime_error("> expects numbers");
    return a->u.num > b->u.num ? make_symbol("t") : make_nil();
}

static Value* builtin_cons(Value* args, Env* env) {
    (void)env;
    if (is_nil(args) || is_nil(args->u.cons.cdr)) return runtime_error("cons expects two arguments");
    return make_cons(args->u.cons.car, args->u.cons.cdr->u.cons.car);
}

static Value* builtin_car(Value* args, Env* env) {
    (void)env;
    if (is_nil(args)) return runtime_error("car expects one argument");
    Value* v = args->u.cons.car;
    if (!is_cons(v)) return runtime_error("car expects a pair");
    return v->u.cons.car;
}

static Value* builtin_cdr(Value* args, Env* env) {
    (void)env;
    if (is_nil(args)) return runtime_error("cdr expects one argument");
    Value* v = args->u.cons.car;
    if (!is_cons(v)) return runtime_error("cdr expects a pair");
    return v->u.cons.cdr;
}

static Value* builtin_list(Value* args, Env* env) {
    (void)env;
    return args;
}

static Value* builtin_append(Value* args, Env* env) {
    (void)env;
    Value* result = NIL;
    while (is_cons(args)) {
        result = append_two(result, args->u.cons.car);
        args = args->u.cons.cdr;
    }
    return result;
}

static Value* builtin_print(Value* args, Env* env) {
    (void)env;
    int first = 1;
    while (is_cons(args)) {
        if (!first) putchar(' ');
        print_value(args->u.cons.car);
        first = 0;
        args = args->u.cons.cdr;
    }
    putchar('\n');
    return NIL;
}

static Value* builtin_not(Value* args, Env* env) {
    (void)env;
    if (is_nil(args)) return runtime_error("not expects one argument");
    return truthy(args->u.cons.car) ? NIL : make_symbol("t");
}

static Value* eval_sequence(Value* body, Env* env) {
    Value* result = NIL;
    while (is_cons(body)) {
        result = eval(body->u.cons.car, env);
        body = body->u.cons.cdr;
    }
    return result;
}

static Value* eval_args(Value* args, Env* env) {
    Value* result = NIL;
    Value* tail = NULL;
    while (is_cons(args)) {
        Value* value = eval(args->u.cons.car, env);
        Value* cell = make_cons(value, NIL);
        if (is_nil(result)) result = cell;
        else tail->u.cons.cdr = cell;
        tail = cell;
        args = args->u.cons.cdr;
    }
    return result;
}

static Value* eval(Value* expr, Env* env) {
    if (!expr || expr->type == TYPE_NIL) return NIL;

    if (expr->type == TYPE_NUMBER) return expr;

    if (expr->type == TYPE_SYMBOL) {
        Value* value = env_get(env, expr->u.sym);
        if (!value) {
            char message[256];
            snprintf(message, sizeof(message), "unbound variable: %s", expr->u.sym);
            return runtime_error(message);
        }
        return value;
    }

    if (expr->type != TYPE_CONS) return expr;

    Value* head = expr->u.cons.car;
    Value* rest = expr->u.cons.cdr;

    if (is_symbol_named(head, "quote")) {
        return is_cons(rest) ? rest->u.cons.car : NIL;
    }

    if (is_symbol_named(head, "quasiquote")) {
        return is_cons(rest) ? qq_eval(rest->u.cons.car, env, 1) : NIL;
    }

    if (is_symbol_named(head, "if")) {
        if (!is_cons(rest)) return runtime_error("if expects a condition");
        Value* condition = eval(rest->u.cons.car, env);
        if (truthy(condition)) {
            return is_cons(rest->u.cons.cdr) ? eval(rest->u.cons.cdr->u.cons.car, env) : NIL;
        } else {
            return (is_cons(rest->u.cons.cdr) && is_cons(rest->u.cons.cdr->u.cons.cdr))
                       ? eval(rest->u.cons.cdr->u.cons.cdr->u.cons.car, env)
                       : NIL;
        }
    }

    if (is_symbol_named(head, "define")) {
        if (!is_cons(rest)) return runtime_error("define expects a target");
        Value* target = rest->u.cons.car;
        if (is_symbol(target)) {
            Value* value = is_cons(rest->u.cons.cdr) ? eval(rest->u.cons.cdr->u.cons.car, env) : NIL;
            env_define(env, target->u.sym, value);
            return value;
        }
        if (is_cons(target) && is_symbol(target->u.cons.car)) {
            Value* params = target->u.cons.cdr;
            Value* body = rest->u.cons.cdr;
            Value* fn = make_lambda(params, body, env);
            env_define(env, target->u.cons.car->u.sym, fn);
            return fn;
        }
        return runtime_error("define expects a symbol or function header");
    }

    if (is_symbol_named(head, "set!")) {
        if (!is_cons(rest) || !is_symbol(rest->u.cons.car)) return runtime_error("set! expects a symbol");
        Value* value = is_cons(rest->u.cons.cdr) ? eval(rest->u.cons.cdr->u.cons.car, env) : NIL;
        if (!env_set(env, rest->u.cons.car->u.sym, value)) {
            return runtime_error("set!: unbound variable");
        }
        return value;
    }

    if (is_symbol_named(head, "lambda")) {
        if (!is_cons(rest)) return runtime_error("lambda expects parameters");
        return make_lambda(rest->u.cons.car, rest->u.cons.cdr, env);
    }

    if (is_symbol_named(head, "let")) {
        if (!is_cons(rest)) return runtime_error("let expects bindings");
        Value* bindings = rest->u.cons.car;
        Value* body = rest->u.cons.cdr;
        Env* child = env_new(env);
        while (is_cons(bindings)) {
            Value* binding = bindings->u.cons.car;
            if (!is_cons(binding) || !is_symbol(binding->u.cons.car)) {
                return runtime_error("let: invalid binding");
            }
            Value* init = is_cons(binding->u.cons.cdr) ? eval(binding->u.cons.cdr->u.cons.car, env) : NIL;
            env_define(child, binding->u.cons.car->u.sym, init);
            bindings = bindings->u.cons.cdr;
        }
        return eval_sequence(body, child);
    }

    if (is_symbol_named(head, "cond")) {
        Value* clauses = rest;
        while (is_cons(clauses)) {
            Value* clause = clauses->u.cons.car;
            if (!is_cons(clause)) return runtime_error("cond: invalid clause");
            Value* test = clause->u.cons.car;
            if (is_symbol_named(test, "else")) {
                return eval_sequence(clause->u.cons.cdr, env);
            }
            Value* test_value = eval(test, env);
            if (truthy(test_value)) {
                if (is_cons(clause->u.cons.cdr)) return eval_sequence(clause->u.cons.cdr, env);
                return test_value;
            }
            clauses = clauses->u.cons.cdr;
        }
        return NIL;
    }

    if (is_symbol_named(head, "progn") || is_symbol_named(head, "begin")) {
        return eval_sequence(rest, env);
    }

    if (is_symbol_named(head, "and")) {
        Value* result = make_symbol("t");
        while (is_cons(rest)) {
            result = eval(rest->u.cons.car, env);
            if (!truthy(result)) return NIL;
            rest = rest->u.cons.cdr;
        }
        return result;
    }

    if (is_symbol_named(head, "or")) {
        while (is_cons(rest)) {
            Value* result = eval(rest->u.cons.car, env);
            if (truthy(result)) return result;
            rest = rest->u.cons.cdr;
        }
        return NIL;
    }

    {
        Value* fn = eval(head, env);
        Value* args = eval_args(rest, env);
        return apply(fn, args, env);
    }
}

static Value* qq_eval(Value* expr, Env* env, int depth) {
    if (!is_cons(expr)) return expr;

    Value* tag = expr->u.cons.car;
    if (is_symbol_named(tag, "unquote")) {
        if (depth == 1) {
            return is_cons(expr->u.cons.cdr) ? eval(expr->u.cons.cdr->u.cons.car, env) : NIL;
        }
        Value* inner = is_cons(expr->u.cons.cdr) ? qq_eval(expr->u.cons.cdr->u.cons.car, env, depth - 1) : NIL;
        return make_cons(make_symbol("unquote"), make_cons(inner, NIL));
    }

    if (is_symbol_named(tag, "quasiquote")) {
        Value* inner = is_cons(expr->u.cons.cdr) ? qq_eval(expr->u.cons.cdr->u.cons.car, env, depth + 1) : NIL;
        return make_cons(make_symbol("quasiquote"), make_cons(inner, NIL));
    }

    Value* result = NIL;
    Value* tail = NULL;
    Value* p = expr;
    while (is_cons(p)) {
        Value* item = p->u.cons.car;
        if (depth == 1 && is_cons(item) && is_symbol_named(item->u.cons.car, "unquote-splicing")) {
            Value* splice = is_cons(item->u.cons.cdr) ? eval(item->u.cons.cdr->u.cons.car, env) : NIL;
            while (is_cons(splice)) {
                Value* cell = make_cons(splice->u.cons.car, NIL);
                if (is_nil(result)) result = cell;
                else tail->u.cons.cdr = cell;
                tail = cell;
                splice = splice->u.cons.cdr;
            }
            if (!is_nil(splice)) return runtime_error("unquote-splicing: expected a list");
        } else {
            Value* cell = make_cons(qq_eval(item, env, depth), NIL);
            if (is_nil(result)) result = cell;
            else tail->u.cons.cdr = cell;
            tail = cell;
        }
        p = p->u.cons.cdr;
    }

    if (!is_nil(p)) {
        Value* last = qq_eval(p, env, depth);
        if (is_nil(result)) return last;
        tail->u.cons.cdr = last;
    }
    return result;
}

static Value* apply(Value* fn, Value* args, Env* env) {
    (void)env;
    if (is_builtin(fn)) {
        return fn->u.builtin(args, env);
    }

    if (!is_lambda(fn)) return runtime_error("attempt to call non-function");

